def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(v for v in set(grid[0]) if all(row.count(v) >= 1 for row in grid))
    # Separator rows/columns are solid lines; remaining colors identify background and marks.
    sep_rows = [r for r in range(h) if all(x == sep for x in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    bg = max(set(x for row in grid for x in row if x != sep),
             key=lambda v: sum(row.count(v) for row in grid))
    mark = next(v for v in set(x for row in grid for x in row) if v not in (sep, bg))

    row_ranges, start = [], 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges, start = [], 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    out = [[bg for _ in col_ranges] for _ in row_ranges]
    for i, (r0, r1) in enumerate(row_ranges):
        for j, (c0, c1) in enumerate(col_ranges):
            count = sum(grid[r][c] == mark for r in range(r0, r1)
                        for c in range(c0, c1))
            if count > 1:
                out[i][j] = 1
    return out
